// HOTELS, TOURS, VEHICLES, ROUTES, STAY_ABOUT, TOUR_ABOUT, STAY_REVIEWS, TOUR_REVIEWS:
// vacíos en build. DataLoader los puebla en runtime desde Supabase mutando in-place.
// Ver src/components/DataLoader.jsx.
const HOTELS = [];

const TOURS = [];
const VEHICLES = [];
const ROUTES = [];
const ORIGINS = ["SJU Airport", "BQN Airport", "San Juan Hotel", "Ponce", "Rincón", "Other"];
const DESTINATIONS = ["Cabo Rojo", "Boquerón", "La Parguera", "Joyuda", "Combate", "SJU Airport", "BQN Airport", "Other"];

const STAY_ABOUT = {};
const TOUR_ABOUT = {};
const STAY_REVIEWS = {};
const TOUR_REVIEWS = {};

/* ═══════════════ DATA LOADER (Supabase → JSX) ═══════════════
   Pobla las constantes mutándolas in-place. PrdiseApp espera dataReady
   antes de renderizar. Esto reemplaza el data set demo eliminado. */

const IMG_BY_SLUG = {
  "aerial-bay": IMG_AERIAL_BAY,
  "palm": IMG_PALM,
  "sunset-jetski": IMG_SUNSET_JETSKI,
  "lighthouse": IMG_LIGHTHOUSE,
  "zipline": IMG_ZIPLINE,
  "mangroves": IMG_MANGROVES,
  "van-road": IMG_VAN_ROAD,
  "sedan": IMG_PALM,
  "suv": IMG_VAN_ROAD,
  "van": IMG_VAN_ROAD,
};
const resolveImg = (slug) => IMG_BY_SLUG[slug] || IMG_PALM;
const resolveImgs = (slugs) => Array.isArray(slugs) && slugs.length ? slugs.map(resolveImg) : [IMG_PALM];

function mapStayToHotel(s) {
  const imgs = Array.isArray(s.images) ? s.images : [];
  return {
    id: s.slug,
    name: s.title_es || s.title_en || s.slug,
    zone: s.location || "",
    type: "Villa",
    price: Math.round((s.price_cents || 0) / 100),
    rating: Number(s.rating_avg) || 0,
    reviews: s.rating_count || 0,
    sleeps: s.max_guests || 1,
    bedrooms: s.bedrooms || 0,
    bathrooms: s.bathrooms || 0,
    img: resolveImg(imgs[0]),
    gallery: resolveImgs(imgs),
    amenities: Array.isArray(s.amenities) ? s.amenities : [],
    desc: s.short_desc_es || s.short_desc_en || "",
    color: s.featured ? "gold" : "sky",
    lat: Number(s.lat) || 0,
    lng: Number(s.lng) || 0,
    status: s.active ? "published" : "hidden",
    bookings: 0,
    rooms: s.bedrooms || 0,
    services: (s.amenities || []).length,
    checkIn: "15:00",
    checkOut: "11:00",
  };
}

function mapTourToTour(t) {
  const imgs = Array.isArray(t.images) ? t.images : [];
  return {
    id: t.slug,
    name: t.title_es || t.title_en || t.slug,
    day: "",
    duration: t.duration_minutes ? `${Math.round(t.duration_minutes / 60)} hours` : "",
    price: Math.round((t.price_cents || 0) / 100),
    rating: Number(t.rating_avg) || 0,
    reviews: t.rating_count || 0,
    capacity: t.max_pax || 1,
    difficulty: t.difficulty || "Easy",
    type: "beach",
    img: resolveImg(imgs[0]),
    gallery: resolveImgs(imgs),
    includes: Array.isArray(t.includes) ? t.includes : [],
    bring: [],
    itinerary: [],
    desc: t.short_desc_es || t.short_desc_en || "",
    color: t.featured ? "gold" : "green",
    location: t.location || "",
    lat: Number(t.lat) || 0,
    lng: Number(t.lng) || 0,
    status: t.active ? "published" : "draft",
    bookings: 0,
  };
}

function mapVehicleToVehicle(v) {
  return {
    id: (v.type || v.name || "").toLowerCase().replace(/\s+/g, "-"),
    name: v.name,
    seats: v.max_pax || 4,
    bags: v.max_luggage || 2,
    base: Math.round((v.price_cents || 0) / 100),
    perKm: 2.5,
    desc: "",
    features: ["A/C", "Pro driver", "Water", "WiFi"],
  };
}

function mapRouteToRoute(r) {
  return {
    from: r.from_location,
    to: r.to_location,
    km: Number(r.distance_km) || 0,
    time: r.duration_minutes ? `${Math.floor(r.duration_minutes / 60)}h ${r.duration_minutes % 60}min` : "",
  };
}

function mapPostToAdminPost(p) {
  return {
    id: p.slug,
    title: p.title_es || p.title_en || p.slug,
    slug: p.slug,
    category: p.category || "",
    author: "",
    date: (p.published_at || p.created_at || "").slice(0, 10),
    status: p.status,
    featured: !!p.featured,
    img: p.image || "IMG_PALM",
    views: p.views || 0,
    excerpt: p.excerpt_es || p.excerpt_en || "",
    body: p.body_es || p.body_en || "",
  };
}

async function loadInitialData() {
  try {
    const [{ createClient }, { getStays, getTours, getTransferRoutes, getVehicles, getPublishedPosts }] = await Promise.all([
      import("@/lib/supabase/client"),
      import("@/lib/queries/catalog"),
    ]);
    const sb = createClient();
    const [stays, tours, routes, vehicles, posts] = await Promise.all([
      getStays(sb),
      getTours(sb),
      getTransferRoutes(sb),
      getVehicles(sb),
      getPublishedPosts(sb, {}),
    ]);

    HOTELS.length = 0;
    (stays || []).forEach((s) => HOTELS.push(mapStayToHotel(s)));

    TOURS.length = 0;
    (tours || []).forEach((t) => TOURS.push(mapTourToTour(t)));

    VEHICLES.length = 0;
    (vehicles || []).forEach((v) => VEHICLES.push(mapVehicleToVehicle(v)));

    ROUTES.length = 0;
    (routes || []).forEach((r) => ROUTES.push(mapRouteToRoute(r)));

    A_POSTS.length = 0;
    (posts || []).forEach((p) => A_POSTS.push(mapPostToAdminPost(p)));
    return true;
  } catch (e) {
    console.error("loadInitialData error:", e);
    return false;
  }
}

const PRDISE = {
  save: (k, v) => { try { localStorage.setItem("prdise_" + k, JSON.stringify(v)); return true; } catch { return false; } },
  load: (k, d = null) => { try { const v = localStorage.getItem("prdise_" + k); return v ? JSON.parse(v) : d; } catch { return d; } },
  del: (k) => { try { localStorage.removeItem("prdise_" + k); } catch {} },
  genRef: (p) => p + "-" + Date.now().toString(36).toUpperCase() + Math.random().toString(36).substr(2, 4).toUpperCase(),
  // Auto-cart: save booking draft to user's cart ONLY if they are logged in.
  // Returns true if saved (user was logged in), false otherwise (no account).
  addToUserCart: (booking) => {
    try {
      const sess = JSON.parse(localStorage.getItem("prdise_session") || "null");
      if (!sess || sess.role !== "user") return false; // No account = don't save
      const cart = JSON.parse(localStorage.getItem("prdise_userCart") || "[]");
      // Dedup: same type + same dates/id = replace instead of duplicating
      const matchKey = booking.type === "hotel"
        ? `hotel:${booking.hotelId}:${booking.checkin}:${booking.checkout}`
        : booking.type === "tour"
          ? `tour:${booking.tourId}:${booking.date}`
          : `transfer:${booking.from}:${booking.to}:${booking.date}`;
      const filtered = cart.filter(c => c._matchKey !== matchKey);
      filtered.unshift({
        ...booking,
        _matchKey: matchKey,
        _cartId: "cart-" + Date.now().toString(36),
        _savedAt: new Date().toISOString(),
        ref: "CART-" + Date.now().toString(36).toUpperCase(),
      });
      // Keep max 10 items
      localStorage.setItem("prdise_userCart", JSON.stringify(filtered.slice(0, 10)));
      try { window.dispatchEvent(new Event("prdise-cart-update")); } catch {}
      return true;
    } catch { return false; }
  },
};
const fmt = (n) => "$" + Number(n).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
const toISO = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;

