function useLang() {
  const [lang, setLangState] = useState(() => PRDISE.load("lang", "en"));
  const setLang = (l) => { PRDISE.save("lang", l); setLangState(l); window.dispatchEvent(new Event("prdise-lang-change")); };
  useEffect(() => {
    const h = () => setLangState(PRDISE.load("lang", "en"));
    window.addEventListener("prdise-lang-change", h);
    window.addEventListener("storage", h);
    return () => { window.removeEventListener("prdise-lang-change", h); window.removeEventListener("storage", h); };
  }, []);
  const t = (key) => (TX[lang] || TX.en)[key] || (TX.en)[key] || key;
  return { lang, setLang, t };
}

/* ═══════════════ ROUTER ═══════════════ */
function useHashRoute() {
  const parse = () => {
    const hash = (typeof window !== "undefined" ? window.location.hash : "") || "#/";
    const clean = hash.replace(/^#/, "") || "/";
    const [path, q = ""] = clean.split("?");
    return { path: path || "/", params: new URLSearchParams(q) };
  };
  const [route, setRoute] = useState(parse());
  useEffect(() => {
    const h = () => { setRoute(parse()); window.scrollTo(0, 0); };
    window.addEventListener("hashchange", h);
    return () => window.removeEventListener("hashchange", h);
  }, []);
  return route;
}
const nav = (p) => { window.location.hash = p.startsWith("#") ? p : "#" + p; };

function NavLink({ to, children, className, style, external, ...rest }) {
  if (external) return <a href={to} target="_blank" rel="noreferrer" className={className} style={style} {...rest}>{children}</a>;
  return <a href={"#" + to} onClick={(e) => { e.preventDefault(); nav(to); }} className={className} style={style} {...rest}>{children}</a>;
}

/* ═══════════════ DATE PICKER ═══════════════ */
function DatePicker({ value, onChange, min, placeholder = "Select date" }) {
  const [open, setOpen] = useState(false);
  const [view, setView] = useState(() => value ? new Date(value + "T12:00") : new Date());
  const ref = useRef(null);

  useEffect(() => {
    const h = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);
  useEffect(() => { if (value) setView(new Date(value + "T12:00")); }, [value]);

  const minDate = min ? new Date(min + "T00:00") : null;
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const selected = value ? new Date(value + "T12:00") : null;
  const year = view.getFullYear(), month = view.getMonth();
  const startOffset = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells = [];
  for (let i = 0; i < startOffset; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d));

  const pick = (d) => { if (!d || (minDate && d < minDate)) return; onChange(toISO(d)); setOpen(false); };
  const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
  const DAYS = ["S", "M", "T", "W", "T", "F", "S"];

  return (
    <div className="dp-wrap" ref={ref}>
      <button type="button" className="dp-trigger" onClick={() => setOpen(!open)}>
        <Calendar className="dp-icon" />
        <span className={selected ? "" : "dp-placeholder"}>
          {selected ? selected.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : placeholder}
        </span>
      </button>
      {open && (
        <div className="dp-popup">
          <div className="dp-head">
            <button type="button" className="dp-nav" onClick={() => setView(new Date(year, month - 1, 1))}><ChevronLeft /></button>
            <div className="dp-title">{MONTHS[month]} {year}</div>
            <button type="button" className="dp-nav" onClick={() => setView(new Date(year, month + 1, 1))}><ChevronRight /></button>
          </div>
          <div className="dp-weekdays">{DAYS.map((d, i) => <span key={i}>{d}</span>)}</div>
          <div className="dp-grid">
            {cells.map((d, i) => {
              if (!d) return <span key={i} className="dp-cell empty" />;
              const iso = toISO(d);
              const isSel = selected && iso === toISO(selected);
              const isToday = iso === toISO(today);
              const isDisabled = minDate && d < minDate;
              return (
                <button type="button" key={i} onClick={() => pick(d)} disabled={isDisabled}
                  className={`dp-cell ${isSel ? "selected" : ""} ${isToday && !isSel ? "today" : ""} ${isDisabled ? "disabled" : ""}`}>
                  {d.getDate()}
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

