/* ═══════════════ HOTELS LIST ═══════════════ */
function HotelsList() {
  const { t, lang } = useLang();
  const L = (en, es) => (lang === "es" && es) ? es : en;
  const [filters, setFilters] = useState({ zones: [], types: [], min: "", max: "" });
  const [sortBy, setSortBy] = useState("featured");
  const [favs, setFavs] = useState([]);
  useEffect(() => { setFavs(PRDISE.load("favs", [])); }, []);
  const zones = useMemo(() => [...new Set(HOTELS.map((h) => h.zone))], []);
  const types = useMemo(() => [...new Set(HOTELS.map((h) => h.type))], []);
  const toggleArr = (k, v) => setFilters((f) => {
    const a = f[k], i = a.indexOf(v);
    return { ...f, [k]: i >= 0 ? a.filter((x) => x !== v) : [...a, v] };
  });
  const filtered = useMemo(() => {
    let list = HOTELS.filter((h) => {
      if (h.status && h.status !== "published") return false;
      if (filters.zones.length && !filters.zones.includes(h.zone)) return false;
      if (filters.types.length && !filters.types.includes(h.type)) return false;
      if (filters.min !== "" && h.price < parseFloat(filters.min)) return false;
      if (filters.max !== "" && h.price > parseFloat(filters.max)) return false;
      return true;
    });
    if (sortBy === "price-asc") list = [...list].sort((a, b) => a.price - b.price);
    else if (sortBy === "price-desc") list = [...list].sort((a, b) => b.price - a.price);
    else if (sortBy === "rating") list = [...list].sort((a, b) => b.rating - a.rating);
    return list;
  }, [filters, sortBy]);
  const toggleFav = (id, e) => {
    e.preventDefault(); e.stopPropagation();
    const next = favs.includes(id) ? favs.filter((f) => f !== id) : [...favs, id];
    setFavs(next); PRDISE.save("favs", next);
  };
  return (
    <>
      <PageHero tag={t("stays")} title={t("availStays")} titleEm="" subtitle="" />
      <div className="inner-page">
        <div className="inner-wrap">

          <div className="layout-2col">
            <aside>
              <div className="panel">
                <div className="panel-title"><SlidersHorizontal style={{width:14,height:14}} />{t("filterTitle")}</div>
                {[{ label: t("zone"), items: zones, key: "zones", field: "zone" }, { label: t("type"), items: types, key: "types", field: "type" }].map((g) => (
                  <div key={g.key} style={{ marginBottom: 14 }}>
                    <label className="panel-label">{g.label}</label>
                    {g.items.map((it) => (
                      <label key={it} className="panel-check">
                        <input type="checkbox" checked={filters[g.key].includes(it)} onChange={() => toggleArr(g.key, it)} />
                        <span style={{flex:1}}>{it}</span>
                        <span className="count">{HOTELS.filter((h) => h[g.field] === it).length}</span>
                      </label>
                    ))}
                  </div>
                ))}
                <div style={{ marginBottom: 14 }}>
                  <label className="panel-label">{t("priceRange")}</label>
                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                    <input className="f-in" type="number" placeholder="Min" value={filters.min} onChange={(e) => setFilters((f) => ({ ...f, min: e.target.value }))} />
                    <input className="f-in" type="number" placeholder="Max" value={filters.max} onChange={(e) => setFilters((f) => ({ ...f, max: e.target.value }))} />
                  </div>
                </div>
                <button onClick={() => setFilters({ zones: [], types: [], min: "", max: "" })} className="cta-sec" style={{ width: "100%", justifyContent: "center", padding: "10px 0" }}>{t("clearAll")}</button>
              </div>
            </aside>
            <main>
              <div className="toolbar">
                <h2>{t("availStays")} <small>({filtered.length})</small></h2>
                <select className="sort-select" value={sortBy} onChange={(e) => setSortBy(e.target.value)}>
                  <option value="featured">{t("sortFeatured")}</option>
                  <option value="price-asc">{t("sortPriceLow")}</option>
                  <option value="price-desc">{t("sortPriceHigh")}</option>
                  <option value="rating">{t("sortRating")}</option>
                </select>
              </div>
              <div className="card-grid">
                {filtered.map((h) => {
                  return (
                    <div key={h.id} className="listing-card">
                      <div className="listing-pic">
                        <img src={h.img} alt={h.name} />
                        <div className="listing-badge" style={{ background: COLORS[h.color] }}>{h.zone}</div>
                      </div>
                      <div className="listing-body">
                        <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, color: "rgba(255,255,255,.5)", marginBottom: 4 }}>
                          <span>{h.type}</span>
                          <span style={{ color: "var(--gold)", fontWeight: 700, display: "flex", alignItems: "center", gap: 4 }}>
                            <Star style={{ width: 12, height: 12, fill: "var(--gold)" }} />{h.rating} ({h.reviews})
                          </span>
                        </div>
                        <h3>{L(h.name, h.nameES)}</h3>
                        <p className="listing-meta"><MapPin style={{ width: 12, height: 12 }} />{h.zone} · Sleeps {h.sleeps}</p>
                        <p className="listing-desc">{L(h.desc, h.descES)}</p>
                        <div className="listing-chips">{(h.amenities || []).slice(0, 4).map((a) => <span key={a}>{a}</span>)}</div>
                        <div className="listing-foot">
                          <div>
                            <span className="price">${h.price}</span>
                            <span className="price-sub">{t("perNight")}</span>
                          </div>
                          <NavLink to={`/stay?id=${h.id}`} className="listing-btn">View <ArrowRight style={{ width: 12, height: 12 }} /></NavLink>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </main>
          </div>
        </div>
      </div>
    </>
  );
}

