// A_* constantes del panel admin: vacías. DataLoader los puebla con datos reales
// de Supabase (profiles, bookings, payments, posts).
const A_VEHICLES = [];
const A_ROUTES = [];
const A_TRANSFER_BOOKINGS = [];
const A_DRIVERS = [];
const A_USERS = [];
const A_ROLES = [];
const A_TRANSACTIONS = [];
