              <button className={`adm-fchip ${toursFilter === "hidden" ? "active" : ""}`} onClick={() => setToursFilter("hidden")}>{lang==="es"?"Ocultos":"Hidden"} <span className="adm-fchip-num">{tours.filter(t => t.status === "hidden").length}</span></button>
